catalog_script_client.script:
function onLoad() {
    // 1. Set 'Requested by' to the current user and make it strictly read-only
    g_form.setValue('requested_by', g_user.userID);
    g_form.setReadOnly('requested_by', true);

    // 2. Set 'Requested for' to current user if empty, but leave it editable
    g_form.setValue('requested_for', g_user.userID);
    g_form.setReadOnly('requested_for', true);

	// 3. Fetch the short description directly from the Catalog Item record
    var catItem = new GlideRecord('sc_cat_item');
    catItem.get(g_form.getUniqueValue(), function(target) {
        if (target.short_description) {
            g_form.setValue('short_description', target.short_description);
        }
        g_form.setReadOnly('short_description', true);
    });
}
